"""Factual observation coverage and compact rank previews."""

CSS = r'''
.overview-list-controls{margin:12px 0}.overview-list-note{font-size:12px;color:#43584c;line-height:1.8;margin:8px 0 12px}.overview-spark{width:144px;height:38px;display:block;margin:auto}.overview-holding,.overview-rating7{min-width:142px!important;white-space:normal}.overview-stat-label{display:block;font-weight:650;font-size:14px}.overview-stat-sub{display:block;color:#61756e;font-size:11px;line-height:1.6;margin-top:4px}.overview-change-table td{vertical-align:middle}.overview-change-table th:first-child,.overview-change-table td:first-child{width:220px;min-width:220px;max-width:220px}.overview-change-table td:nth-child(2){white-space:normal;max-width:170px}.overview-change-table th:nth-child(4),.overview-change-table td:nth-child(4){min-width:160px}.overview-stat-unknown{font-weight:500;color:#61756e}
@media(max-width:760px){.overview-change-table th:first-child,.overview-change-table td:first-child{width:128px;min-width:128px;max-width:128px}.overview-list-controls label{flex:1;min-width:135px}}
'''

HTML = r'''
<div class="toolbar overview-list-controls"><label>展示方式<select id="overview-view"><option value="changes" selected>变化列表 · 小折线与统计</option><option value="matrix">逐日对照表</option></select></label><label>逐日对照表指标<select id="overview-metric"><option value="rank">逐日排名（名）</option><option value="daily">每日新增评分（条）</option><option value="total">累计评分（条）</option></select></label></div>
<p id="overview-stat-note" class="overview-list-note"></p><h3 id="overview-table-title" class="overview-table-title"></h3>
<div class="tablewrap overview-matrix" id="overview-changes-scroll" tabindex="0" aria-label="产品变化列表，可横向滚动"><table class="overview-change-table"><thead><tr><th scope="col">产品</th><th scope="col">报告当日排名 / 状态</th><th scope="col">排名起止日变化</th><th scope="col">排名小折线 · #1在上方</th><th scope="col">持榜天数 · 所选日期</th><th scope="col">近7日新增评分 · 有效日合计</th></tr></thead><tbody id="overview-changes"></tbody></table><div id="overview-changes-empty" class="empty" hidden></div></div>
'''

JS = r'''
function holdingStats(p,kind,dates){const rows=dates.map(day=>p.observations.find(r=>r.date===day)),ranked=rows.filter(r=>numberValue(r?.[kind+'_rank'])),assessable=rows.filter(r=>numberValue(r?.[kind+'_rank'])||r?.[kind+'_status']==='off_chart');return {ranked:ranked.length,assessable:assessable.length,days:dates.length,unknown:dates.length-assessable.length,short:rows.filter(r=>!numberValue(r?.[kind+'_rank'])&&r?.[kind+'_status']==='not_returned').length,missing:rows.filter(r=>!r||r[kind+'_status']==='missing').length,best:ranked.length?Math.min(...ranked.map(r=>r[kind+'_rank'])):null,last:ranked.length?ranked[ranked.length-1].date:null};}
function ratingWeek(p){if(p.rating_7d?.end===data.as_of)return p.rating_7d;const end=new Date(data.as_of+'T00:00:00Z'),days=Array.from({length:7},(_,i)=>{const d=new Date(end);d.setUTCDate(d.getUTCDate()-6+i);return d.toISOString().slice(0,10);}),valid=days.map(day=>p.observations.find(r=>r.date===day)?.rating_delta_1d).filter(v=>numberValue(v)&&v>=0);return {start:days[0],end:data.as_of,expected_days:7,valid_days:valid.length,sum:valid.length?valid.reduce((a,b)=>a+b,0):null,complete:valid.length===7};}
function rankSparkline(p,kind,dates){const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg'),W=144,H=38,xx=i=>4+(dates.length===1?68:i*136/(dates.length-1)),yy=v=>4+(v-1)/99*30;svg.classList.add('overview-spark');svg.setAttribute('viewBox',`0 0 ${W} ${H}`);svg.setAttribute('role','img');svg.setAttribute('aria-label',p.name+'，所选'+dates.length+'个日期的排名，统一第1至100名，缺失断线');svg.dataset.appId=p.app_id;let part=[];function flush(){if(part.length>1){const line=document.createElementNS(ns,'polyline');line.setAttribute('points',part.join(' '));line.setAttribute('fill','none');line.setAttribute('stroke','#176f53');line.setAttribute('stroke-width','2');svg.append(line);}part=[];}dates.forEach((day,i)=>{const r=p.observations.find(r=>r.date===day),rank=r?.[kind+'_rank'];if(!numberValue(rank)){flush();return;}part.push(xx(i)+','+yy(rank));});flush();dates.forEach((day,i)=>{const r=p.observations.find(r=>r.date===day),rank=r?.[kind+'_rank'];if(!numberValue(rank))return;const dot=document.createElementNS(ns,'circle');for(const [key,v]of Object.entries({cx:xx(i),cy:yy(rank),r:2,fill:'#176f53','data-date':day,'data-value':rank}))dot.setAttribute(key,String(v));const title=document.createElementNS(ns,'title');title.textContent=day+' · 第'+rank+'名';dot.append(title);svg.append(dot);});return svg;}
function appendHoldingCell(tr,stats){const td=node('td',null,'overview-holding');td.dataset.heldDays=stats.ranked;td.dataset.validDays=stats.assessable;td.dataset.unknownDays=stats.unknown;td.append(node('span',stats.ranked+'天已上榜','overview-stat-label'),node('span','可判定'+stats.assessable+'/'+stats.days+'天'+(stats.unknown?' · '+stats.unknown+'天未知':''),'overview-stat-sub'));td.title='上榜'+stats.ranked+'天；完整榜未出现或明确上榜时才可判定。短榜未返'+stats.short+'天；观测缺失'+stats.missing+'天。未知不当作离榜。';tr.append(td);}
function appendRatingWeekCell(tr,p){const week=ratingWeek(p),td=node('td',null,'overview-rating7');td.dataset.value=numberValue(week.sum)?String(week.sum):'';td.dataset.validDays=week.valid_days;td.dataset.expectedDays=7;td.append(node('span',numberValue(week.sum)?fmt(week.sum)+'条':'无可计算数据','overview-stat-label'+(week.valid_days?'':' overview-stat-unknown')),node('span','有效'+week.valid_days+'/7天'+(!week.complete&&week.valid_days?' · 部分合计':''),'overview-stat-sub'));td.title=week.start+' 至 '+week.end+'，只合计'+week.valid_days+'个可计算日期；缺失或回退不补零、不跨缺日计算。';tr.append(td);}
'''
